    vector<int> cost(n / 2, 0);

    while (idx < n) {
        int depth = 0;
        int costSum = 0;

        while (s[idx++] != '_') {
            if (s[idx - 1] == '(')
                depth++;
            else
                depth--;

            costSum += depth;
        }

        cost[idx / 2 - 1] = costSum;
    }

